function parseJson<T>(s: string | null | undefined, fallback: T): T {
  try {
    return s ? (JSON.parse(s) as T) : fallback;
  } catch {
    return fallback;
  }
}

function favArtistFromRow(r: FavArtistRow): FavArtist {
  return {
    key: r.artist_key,
    name: r.name,
    ytId: r.yt_id ?? undefined,
    thumbnail: r.thumbnail ?? undefined,
    addedAt: r.added_at,
    fresh: parseJson<AlbumRef | null>(r.fresh, null),
    releases: parseJson<AlbumRef[]>(r.releases, []),
    checkedAt: r.checked_at,
  };
}

const cleanUrl = (u: unknown): string | null => (typeof u === 'string' && /^https:\/\//.test(u) ? u.slice(0, 1000) : null);

/** Релизы из окна проверяем: только понятные поля, не больше 60 штук. */
function cleanReleases(list: unknown): AlbumRef[] {
  if (!Array.isArray(list)) return [];
  return list
    .filter((r): r is AlbumRef => !!r && typeof r.id === 'string' && /^MPRE[\w-]{5,40}$/.test(r.id))
    .slice(0, 60)
    .map((r) => ({
      id: r.id,
      title: String(r.title ?? '').slice(0, 300),
      year: typeof r.year === 'string' ? r.year.slice(0, 4) : undefined,
      thumbnail: cleanUrl(r.thumbnail) ?? undefined,
      kind: r.kind === 'single' ? 'single' : 'album',
    }));
}

function savedAlbumFromRow(r: SavedAlbumRow): SavedAlbum {
  return {
    id: r.album_id,
    title: r.title,
    artist: r.artist,
    artistId: r.artist_id ?? undefined,
    year: r.year ?? undefined,
    thumbnail: r.thumbnail ?? undefined,
    tracks: parseJson<Candidate[]>(r.tracks, []),
    addedAt: r.added_at,
  };
}

