/** Ошибка, которую можно показать пользователю как есть. */
export class ProfileError extends Error {
  constructor(
    public code: 'bad_name' | 'bad_password' | 'name_taken' | 'wrong_login' | 'not_logged_in' | 'not_found' | 'bad_input',
    message: string,
  ) {
    super(message);
  }
}

const NAME_RE = /^[\p{L}\p{N}_.\- ]{2,32}$/u;

/** Ключ для сравнения имён без учёта регистра (работает и для кириллицы). */
const nameKey = (name: string) => String(name ?? '').trim().toLowerCase();
const MIN_PASSWORD = 6;
const HISTORY_LIMIT = 200;

interface PlaylistRow {
  id: number;
  name: string;
  description: string;
  custom: string | null;
  trackCount: number;
}

interface TrackRow {
  source: Source;
  source_id: string;
  title: string;
  artist: string;
  duration: number | null;
  url: string;
  thumbnail: string | null;
}

/**
 * Обложка своего файла (1.7): адрес локального прокси меняется при каждом запуске,
 * поэтому в базе её не храним, а спрашиваем у модуля своих файлов (задаёт главный процесс).
 */
export const localCover: { url: (id: string) => string | undefined } = { url: () => undefined };

function rowToCandidate(r: TrackRow): Candidate {
  return {
    source: r.source,
    id: r.source_id,
    title: r.title,
    artist: r.artist,
    duration: r.duration,
    url: r.url,
    thumbnail: r.source === 'local' ? localCover.url(r.source_id) : (r.thumbnail ?? undefined),
  };
}

/** Проверка трека, пришедшего из окна: не доверяем данным вслепую. */
function checkCandidate(c: Candidate): Candidate {
  const ok =
    c &&
    (c.source === 'ytmusic' || c.source === 'soundcloud' || c.source === 'local') &&
    typeof c.id === 'string' && c.id.length > 0 && c.id.length < 300 &&
    typeof c.title === 'string' && c.title.length < 500 &&
    typeof c.artist === 'string' && c.artist.length < 500 &&
    typeof c.url === 'string' && (c.source === 'local' ? c.url === `mwave-local://${c.id}` : /^https:\/\//.test(c.url));
  if (!ok) throw new ProfileError('bad_input', 'Некорректные данные трека');
  return c;
}

export class ProfileStore {
  checkpoint(): void { this.db.exec('PRAGMA wal_checkpoint(TRUNCATE)'); }
  private user: User | null = null;

  /** Как превратить имя файла своей обложки плейлиста в адрес для окна (задаёт главный процесс). */
  coverUrl: (file: string) => string | undefined = () => undefined;

  constructor(private db: DB) {
    // Если в прошлый раз нажали "запомнить меня", входим автоматически
    const remembered = this.getSetting('remembered_user');
    if (remembered) {
      const u = db.prepare('SELECT id, name FROM users WHERE id = ?').get(Number(remembered)) as User | undefined;
      if (u) this.user = u;
    }
  }

  // ---------- вход ----------

  currentUser(): User | null {
    return this.user;
  }

  /** Main-only: called after a verified server login and lookup by bound account UUID. */
  openCloudProfile(id: number, remember = true): User {
    const row=this.db.prepare('SELECT id,name FROM users WHERE id=?').get(id) as User|undefined;
    if(!row)throw new ProfileError('not_found','Локальный профиль не найден');
    return this.startSession(row,remember);
  }

  async register(name: string, password: string, remember: boolean): Promise<User> {
    const clean = String(name ?? '').trim();
    if (!NAME_RE.test(clean)) {
      throw new ProfileError('bad_name', 'Имя: от 2 до 32 символов (буквы, цифры, пробел, _ . -)');
    }
    if (String(password ?? '').length < MIN_PASSWORD) {
      throw new ProfileError('bad_password', `Пароль: не короче ${MIN_PASSWORD} символов`);
    }
    if (this.db.prepare('SELECT 1 FROM users WHERE name_key = ?').get(nameKey(clean))) {
      throw new ProfileError('name_taken', 'Такое имя уже есть на этом компьютере');
    }
    const hash = await hashPassword(password);
    const info = this.db
      .prepare('INSERT INTO users (name, name_key, pass_hash, created_at) VALUES (?, ?, ?, ?)')
      .run(clean, nameKey(clean), hash, Date.now());
    return this.startSession({ id: Number(info.lastInsertRowid), name: clean }, remember);
  }

  async login(name: string, password: string, remember: boolean): Promise<User> {
    const row = this.db
      .prepare('SELECT id, name, pass_hash FROM users WHERE name_key = ?')
      .get(nameKey(name)) as (User & { pass_hash: string }) | undefined;
    // Одинаковое сообщение для "нет такого имени" и "неверный пароль"
    if (!row || !(await verifyPassword(String(password ?? ''), row.pass_hash))) {
      throw new ProfileError('wrong_login', 'Неверное имя или пароль');
    }
    return this.startSession({ id: row.id, name: row.name }, remember);
  }

  logout(): void {
    this.user = null;
    this.db.prepare("DELETE FROM settings WHERE key = 'remembered_user'").run();
  }

  private startSession(user: User, remember: boolean): User {
    this.user = user;
    if (remember) this.setSetting('remembered_user', String(user.id));
    else this.db.prepare("DELETE FROM settings WHERE key = 'remembered_user'").run();
    return user;
  }

  private requireUser(): User {
    if (!this.user) throw new ProfileError('not_logged_in', 'Сначала войди в профиль');
    return this.user;
  }

  // ---------- треки ----------

  /** Сохраняет трек в таблицу tracks (или обновляет название/обложку) и возвращает его id. */
  private upsertTrack(c: Candidate): number {
    const t = checkCandidate(c);
    this.db
      .prepare(
        `INSERT INTO tracks (source, source_id, title, artist, duration, url, thumbnail)
         VALUES (@source, @id, @title, @artist, @duration, @url, @thumbnail)
         ON CONFLICT (source, source_id) DO UPDATE SET
           title = excluded.title, artist = excluded.artist, duration = COALESCE(excluded.duration, tracks.duration),
           url = excluded.url, thumbnail = COALESCE(excluded.thumbnail, tracks.thumbnail)`,
      )
      .run({ ...t, duration: t.duration ?? null, thumbnail: t.thumbnail ?? null });
    const row = this.db
      .prepare('SELECT id FROM tracks WHERE source = ? AND source_id = ?')
      .get(t.source, t.id) as { id: number };
    return row.id;
  }

  // ---------- избранное ----------

  /** Добавляет в избранное или убирает. Возвращает новое состояние (true = в избранном). */
  toggleFavorite(c: Candidate): boolean {
    const u = this.requireUser();
    return this.db.transaction(() => {
      const trackId = this.upsertTrack(c);
      const del = this.db.prepare('DELETE FROM favorites WHERE user_id = ? AND track_id = ?').run(u.id, trackId);
      if (del.changes > 0) return false;
      this.db.prepare('INSERT INTO favorites (user_id, track_id, added_at) VALUES (?, ?, ?)').run(u.id, trackId, Date.now());
      return true;
    })();
  }

  /** Избранное, новые сверху. */
  listFavorites(): Candidate[] {
    const u = this.requireUser();
    const rows = this.db
      .prepare(
        `SELECT t.* FROM favorites f JOIN tracks t ON t.id = f.track_id
         WHERE f.user_id = ? ORDER BY f.added_at DESC, f.rowid DESC`,
      )
      .all(u.id) as TrackRow[];
    return rows.map(rowToCandidate);
  }

  /**
   * Добавить песни в любимые (импорт): уже имеющиеся не трогаем. Порядок: первая песня списка
   * окажется наверху (как в выгрузке Spotify, где новые сверху). Возвращает, сколько добавлено и сколько уже было.
   */
  addFavorites(list: Candidate[]): { added: number; duplicates: number } {
    const u = this.requireUser();
    if (!Array.isArray(list) || list.length > 10_000) throw new ProfileError('bad_input', 'Некорректный список треков');
    return this.db.transaction(() => {
      let added = 0;
      let duplicates = 0;
      const now = Date.now();
      // Снизу вверх: у первой песни списка самая поздняя дата добавления
      [...list].reverse().forEach((c, i) => {
        const trackId = this.upsertTrack(c);
        const r = this.db.prepare('INSERT OR IGNORE INTO favorites (user_id, track_id, added_at) VALUES (?, ?, ?)').run(u.id, trackId, now + i);
        if (Number(r.changes)) added++;
        else duplicates++;
      });
      return { added, duplicates };
    })();
  }

  /** Любимые треки с датой добавления (для сортировки), новые сверху. */
  listFavoritesDetailed(): FavoriteEntry[] {
    const u = this.requireUser();
    const rows = this.db
      .prepare(
        `SELECT f.added_at AS fav_added, t.* FROM favorites f JOIN tracks t ON t.id = f.track_id
         WHERE f.user_id = ? ORDER BY f.added_at DESC, f.rowid DESC`,
      )
      .all(u.id) as (TrackRow & { fav_added: number })[];
    return rows.map((r) => ({ track: rowToCandidate(r), addedAt: r.fav_added }));
  }

  /** Ключи "источник:id" всех избранных треков: окно по ним рисует сердечки. */
  favoriteKeys(): string[] {
    const u = this.requireUser();
    const rows = this.db
      .prepare('SELECT t.source, t.source_id FROM favorites f JOIN tracks t ON t.id = f.track_id WHERE f.user_id = ?')
      .all(u.id) as { source: string; source_id: string }[];
    return rows.map((r) => `${r.source}:${r.source_id}`);
  }

  // ---------- плейлисты ----------

  listPlaylists(): PlaylistInfo[] {
    const u = this.requireUser();
    const rows = this.db
      .prepare(
        `SELECT p.id, p.name, p.description, p.cover AS custom, COUNT(i.id) AS trackCount
         FROM playlists p LEFT JOIN playlist_items i ON i.playlist_id = p.id
         WHERE p.user_id = ? GROUP BY p.id ORDER BY p.created_at, p.id`,
      )
      .all(u.id) as PlaylistRow[];
    return rows.map((r) => this.playlistInfo(r));
  }

  /** Один плейлист (шапка страницы). */
  playlist(id: number): PlaylistInfo {
    this.ownPlaylist(id);
    const r = this.db
      .prepare(
        `SELECT p.id, p.name, p.description, p.cover AS custom,
           (SELECT COUNT(*) FROM playlist_items i WHERE i.playlist_id = p.id) AS trackCount
         FROM playlists p WHERE p.id = ?`,
      )
      .get(id) as PlaylistRow;
    return this.playlistInfo(r);
  }

  /** Обложки первых песен плейлиста (до 4 разных) для мозаики. */
  private mosaic(id: number): string[] {
    const rows = this.db
      .prepare(
        `SELECT t.thumbnail FROM playlist_items i JOIN tracks t ON t.id = i.track_id
         WHERE i.playlist_id = ? AND t.thumbnail IS NOT NULL ORDER BY i.position, i.id LIMIT 40`,
      )
      .all(id) as { thumbnail: string }[];
    return [...new Set(rows.map((r) => r.thumbnail))].slice(0, 4);
  }

  private playlistInfo(r: PlaylistRow): PlaylistInfo {
    const covers = this.mosaic(r.id);
    const custom = r.custom ? this.coverUrl(r.custom) : undefined;
    return {
      id: r.id,
      name: r.name,
      trackCount: r.trackCount,
      description: r.description ?? '',
      covers,
      cover: custom ?? covers[0],
      customCover: !!custom,
    };
  }

  /** Описание плейлиста (до 300 символов). */
  setPlaylistDescription(id: number, text: string): void {
    this.ownPlaylist(id);
    this.db.prepare('UPDATE playlists SET description = ? WHERE id = ?').run(String(text ?? '').trim().slice(0, 300), id);
  }

  /** Своя обложка (имя файла в папке covers) или null: снова мозаика. Возвращает прежний файл, чтобы его удалить. */
  setPlaylistCover(id: number, file: string | null): string | null {
    this.ownPlaylist(id);
    if (file !== null && !/^[\w.-]{1,80}$/.test(file)) throw new ProfileError('bad_input', 'Неверный файл обложки');
    const old = (this.db.prepare('SELECT cover FROM playlists WHERE id = ?').get(id) as { cover: string | null }).cover;
    this.db.prepare('UPDATE playlists SET cover = ? WHERE id = ?').run(file, id);
    return old;
  }

  /** Все файлы своих обложек (чтобы не удалить нужный при уборке). */
  coverFiles(): string[] {
    return (this.db.prepare('SELECT cover FROM playlists WHERE cover IS NOT NULL').all() as { cover: string }[]).map((r) => r.cover);
  }

  createPlaylist(name: string): PlaylistInfo {
    const u = this.requireUser();
    const clean = this.checkPlaylistName(name);
    const info = this.db
      .prepare('INSERT INTO playlists (user_id, name, created_at) VALUES (?, ?, ?)')
      .run(u.id, clean, Date.now());
    return { id: Number(info.lastInsertRowid), name: clean, trackCount: 0 };
  }

  /** Создаёт плейлист сразу с треками (для импорта). Всё или ничего: одна транзакция. */
  createPlaylistWithTracks(name: string, tracks: Candidate[]): PlaylistInfo & { duplicates: number } {
    if (!Array.isArray(tracks) || tracks.length > 10_000) throw new ProfileError('bad_input', 'Некорректный список треков');
    // Одна и та же песня дважды (в выгрузке или после ручного выбора) добавляется один раз
    const seen = new Set<string>();
    const unique = tracks.filter((t) => {
      const k = `${t?.source}:${t?.id}`;
      if (seen.has(k)) return false;
      seen.add(k);
      return true;
    });
    return this.db.transaction(() => {
      const pl = this.createPlaylist(name);
      for (const t of unique) this.addToPlaylist(pl.id, t);
      return { ...pl, trackCount: unique.length, duplicates: tracks.length - unique.length };
    })();
  }

  renamePlaylist(id: number, name: string): void {
    this.ownPlaylist(id);
    this.db.prepare('UPDATE playlists SET name = ? WHERE id = ?').run(this.checkPlaylistName(name), id);
  }

  /** Удаляет плейлист. Возвращает файл его своей обложки (если был), чтобы удалить и его. */
  deletePlaylist(id: number): string | null {
    this.ownPlaylist(id);
    const row = this.db.prepare('SELECT cover FROM playlists WHERE id = ?').get(id) as { cover: string | null };
    this.db.prepare('DELETE FROM playlists WHERE id = ?').run(id);
    return row.cover;
  }

  playlistTracks(id: number): PlaylistItem[] {
    this.ownPlaylist(id);
    const rows = this.db
      .prepare(
        `SELECT i.id AS item_id, i.added_at AS item_added, t.* FROM playlist_items i JOIN tracks t ON t.id = i.track_id
         WHERE i.playlist_id = ? ORDER BY i.position, i.id`,
      )
      .all(id) as (TrackRow & { item_id: number; item_added: number })[];
    return rows.map((r) => ({ itemId: r.item_id, track: rowToCandidate(r), addedAt: r.item_added }));
  }

  /** Есть ли песня в плейлисте (для предупреждения «уже есть»). */
  playlistHas(id: number, c: Candidate): boolean {
    this.ownPlaylist(id);
    return !!this.db
      .prepare(
        `SELECT 1 FROM playlist_items i JOIN tracks t ON t.id = i.track_id
         WHERE i.playlist_id = ? AND t.source = ? AND t.source_id = ?`,
      )
      .get(id, c?.source, c?.id);
  }

  /** Добавляет трек в конец плейлиста. */
  addToPlaylist(id: number, c: Candidate): void {
    this.ownPlaylist(id);
    this.db.transaction(() => {
      const trackId = this.upsertTrack(c);
      const { next } = this.db
        .prepare('SELECT COALESCE(MAX(position), -1) + 1 AS next FROM playlist_items WHERE playlist_id = ?')
        .get(id) as { next: number };
      this.db
        .prepare('INSERT INTO playlist_items (playlist_id, track_id, position, added_at) VALUES (?, ?, ?, ?)')
        .run(id, trackId, next, Date.now());
    })();
  }

  removeFromPlaylist(id: number, itemId: number): void {
    this.removeItems(id, [itemId]);
  }

  /** Убирает строки из плейлиста. Возвращает их (песня, место, дата), чтобы «Отменить» вернуло их. */
  removeItems(id: number, itemIds: number[]): RemovedItem[] {
    this.ownPlaylist(id);
    if (!Array.isArray(itemIds) || itemIds.length > 5000) throw new ProfileError('bad_input', 'Некорректный список');
    return this.db.transaction(() => {
      const out: RemovedItem[] = [];
      for (const itemId of itemIds) {
        const row = this.db
          .prepare(
            `SELECT i.position AS item_pos, i.added_at AS item_added, t.* FROM playlist_items i JOIN tracks t ON t.id = i.track_id
             WHERE i.id = ? AND i.playlist_id = ?`,
          )
          .get(Number(itemId), id) as (TrackRow & { item_pos: number; item_added: number }) | undefined;
        if (!row) continue;
        this.db.prepare('DELETE FROM playlist_items WHERE id = ? AND playlist_id = ?').run(Number(itemId), id);
        out.push({ track: rowToCandidate(row), position: row.item_pos, addedAt: row.item_added });
      }
      return out;
    })();
  }

  /** «Отменить» удаление: строки возвращаются на прежние места с прежней датой добавления. */
  restoreItems(id: number, items: RemovedItem[]): void {
    this.ownPlaylist(id);
    if (!Array.isArray(items) || items.length > 5000) throw new ProfileError('bad_input', 'Некорректный список');
    this.db.transaction(() => {
      for (const it of items) {
        const trackId = this.upsertTrack(it.track);
        this.db
          .prepare('INSERT INTO playlist_items (playlist_id, track_id, position, added_at) VALUES (?, ?, ?, ?)')
          .run(id, trackId, Number(it.position) || 0, Number(it.addedAt) || Date.now());
      }
    })();
  }

  /**
   * Свой порядок: строки плейлиста в указанном порядке (перетаскивание мышью или «Отменить»).
   * Строки, которых нет в списке, встают после указанных в прежнем порядке.
   */
  reorderPlaylist(id: number, itemIds: number[]): void {
    this.ownPlaylist(id);
    if (!Array.isArray(itemIds) || itemIds.length > 5000) throw new ProfileError('bad_input', 'Некорректный порядок');
    this.db.transaction(() => {
      const all = (this.db.prepare('SELECT id FROM playlist_items WHERE playlist_id = ? ORDER BY position, id').all(id) as { id: number }[]).map((r) => r.id);
      const known = new Set(all);
      const given = [...new Set(itemIds.map(Number).filter((x) => known.has(x)))];
      const rest = all.filter((x) => !given.includes(x));
      const st = this.db.prepare('UPDATE playlist_items SET position = ? WHERE id = ? AND playlist_id = ?');
      [...given, ...rest].forEach((itemId, pos) => st.run(pos, itemId, id));
    })();
  }

  private checkPlaylistName(name: string): string {
    const clean = String(name ?? '').trim();
    if (clean.length < 1 || clean.length > 60) throw new ProfileError('bad_input', 'Название плейлиста: от 1 до 60 символов');
    return clean;
  }

  /** Плейлист должен принадлежать текущему пользователю. */
  private ownPlaylist(id: number): void {
    const u = this.requireUser();
    const row = this.db.prepare('SELECT 1 FROM playlists WHERE id = ? AND user_id = ?').get(Number(id), u.id);
    if (!row) throw new ProfileError('not_found', 'Плейлист не найден');
  }

  // ---------- история ----------

  /**
   * Записывает прослушивание. Храним последние HISTORY_LIMIT записей на пользователя.
   * Для статистики (1.7) то же прослушивание пишется в plays без ограничения; возвращает его номер,
   * по которому окно потом сообщает, сколько секунд песня реально звучала (setPlayed).
   */
  addHistory(c: Candidate): number {
    const u = this.requireUser();
    return this.db.transaction(() => {
      const trackId = this.upsertTrack(c);
      const now = Date.now();
      this.db.prepare('INSERT INTO history (user_id, track_id, played_at) VALUES (?, ?, ?)').run(u.id, trackId, now);
      // Прослушивание засчитывается после 30 секунд: столько уже прозвучало, дальше окно уточнит
      const first = Math.min(30, c.duration && c.duration > 0 ? c.duration : 30);
      const play = this.db.prepare('INSERT INTO plays (user_id, track_id, played_at, played_s) VALUES (?, ?, ?, ?)').run(u.id, trackId, now, first);
      this.db
        .prepare(
          `DELETE FROM history WHERE user_id = ? AND id NOT IN
           (SELECT id FROM history WHERE user_id = ? ORDER BY played_at DESC, id DESC LIMIT ?)`,
        )
        .run(u.id, u.id, HISTORY_LIMIT);
      return Number(play.lastInsertRowid);
    })();
  }

  /** Сколько секунд прослушивание реально звучало (окно сообщает по ходу и в конце песни). */
  setPlayed(playId: number, seconds: number): void {
    const u = this.requireUser();
    if (!Number.isFinite(seconds) || seconds < 0) return;
    this.db.prepare('UPDATE plays SET played_s = ? WHERE id = ? AND user_id = ?').run(Math.min(seconds, 3 * 3600), Number(playId), u.id);
  }

  /** Прослушивания с момента since (для статистики). seconds = null: старая запись, время неизвестно. */
  playsSince(since: number): { track: Candidate; playedAt: number; seconds: number | null }[] {
    const u = this.requireUser();
    const rows = this.db
      .prepare(
        `SELECT p.played_at AS p_at, p.played_s AS p_s, t.* FROM plays p JOIN tracks t ON t.id = p.track_id
         WHERE p.user_id = ? AND p.played_at >= ? ORDER BY p.played_at`,
      )
      .all(u.id, since) as (TrackRow & { p_at: number; p_s: number | null })[];
    return rows.map((r) => ({ track: rowToCandidate(r), playedAt: r.p_at, seconds: r.p_s }));
  }

  listHistory(limit = 100): HistoryEntry[] {
    const u = this.requireUser();
    const rows = this.db
      .prepare(
        `SELECT h.id AS h_id, h.played_at, t.* FROM history h JOIN tracks t ON t.id = h.track_id
         WHERE h.user_id = ? ORDER BY h.played_at DESC, h.id DESC LIMIT ?`,
      )
      .all(u.id, Math.min(Math.max(1, Number(limit) || 100), HISTORY_LIMIT)) as (TrackRow & { h_id: number; played_at: number })[];
    return rows.map((r) => ({ id: r.h_id, playedAt: r.played_at, track: rowToCandidate(r) }));
  }

  /** Песни, звучавшие за последние hours часов (для "Бесконечной музыки": не повторять). Без входа: пусто. */
  recentTracks(hours: number): Candidate[] {
    if (!this.user) return [];
    const since = Date.now() - hours * 60 * 60_000;
    const rows = this.db
      .prepare(
        `SELECT DISTINCT t.* FROM history h JOIN tracks t ON t.id = h.track_id
         WHERE h.user_id = ? AND h.played_at >= ?`,
      )
      .all(this.user.id, since) as TrackRow[];
    return rows.map(rowToCandidate);
  }

  // ---------- настройки пользователя ----------

  /** Настройка текущего пользователя (например, "Бесконечная музыка") или null, если не задана. */
  getUserPref(name: string): string | null {
    const u = this.requireUser();
    return this.getSetting(`user:${u.id}:${name}`);
  }

  setUserPref(name: string, value: string): void {
    const u = this.requireUser();
    this.setSetting(`user:${u.id}:${name}`, String(value).slice(0, 200));
  }

  clearHistory(): void {
    const u = this.requireUser();
    this.db.prepare('DELETE FROM history WHERE user_id = ?').run(u.id);
  }

  // ---------- главная: самые слушаемые плейлисты ----------

  /** Плейлисты, песни из которых чаще всего звучали за последние 30 дней (для плиток главной). */
  topPlaylists(limit = 4): (PlaylistInfo & { plays: number; cover?: string })[] {
    const u = this.requireUser();
    const since = Date.now() - 30 * 24 * 60 * 60_000;
    const rows = this.db
      .prepare(
        `SELECT p.id, p.name,
           (SELECT COUNT(*) FROM playlist_items i WHERE i.playlist_id = p.id) AS trackCount,
           (SELECT COUNT(*) FROM history h WHERE h.user_id = p.user_id AND h.played_at >= ?
              AND h.track_id IN (SELECT track_id FROM playlist_items WHERE playlist_id = p.id)) AS plays,
           (SELECT t.thumbnail FROM playlist_items i JOIN tracks t ON t.id = i.track_id
              WHERE i.playlist_id = p.id AND t.thumbnail IS NOT NULL ORDER BY i.position LIMIT 1) AS cover,
           p.cover AS custom
         FROM playlists p WHERE p.user_id = ? ORDER BY plays DESC, p.created_at DESC LIMIT ?`,
      )
      .all(since, u.id, Math.max(1, Math.min(20, limit))) as (PlaylistInfo & { plays: number; cover: string | null; custom: string | null })[];
    return rows.map(({ custom, ...r }) => ({ ...r, cover: (custom ? this.coverUrl(custom) : undefined) ?? r.cover ?? undefined }));
  }

  // ---------- сохранённые альбомы ----------

  /** Сохранить альбом в медиатеку (или обновить снимок). */
  saveAlbum(a: Omit<SavedAlbum, 'addedAt'>): void {
    const u = this.requireUser();
    const id = String(a?.id ?? '');
    if (!/^MPRE[\w-]{5,40}$/.test(id)) throw new ProfileError('bad_input', 'Неверный альбом');
    const tracks = (Array.isArray(a.tracks) ? a.tracks : []).slice(0, 300).map(checkCandidate);
    this.db
      .prepare(
        `INSERT INTO saved_albums (user_id, album_id, title, artist, artist_id, year, thumbnail, tracks, added_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT (user_id, album_id) DO UPDATE SET title = excluded.title, artist = excluded.artist,
           artist_id = excluded.artist_id, year = excluded.year, thumbnail = excluded.thumbnail, tracks = excluded.tracks`,
      )
      .run(
        u.id,
        id,
        String(a.title ?? '').slice(0, 300),
        String(a.artist ?? '').slice(0, 300),
        typeof a.artistId === 'string' && /^UC[\w-]{10,40}$/.test(a.artistId) ? a.artistId : null,
        typeof a.year === 'string' ? a.year.slice(0, 4) : null,
        cleanUrl(a.thumbnail),
        JSON.stringify(tracks),
        Date.now(),
      );
  }

  unsaveAlbum(id: string): void {
    const u = this.requireUser();
    this.db.prepare('DELETE FROM saved_albums WHERE user_id = ? AND album_id = ?').run(u.id, String(id));
  }

  isAlbumSaved(id: string): boolean {
    if (!this.user) return false;
    return !!this.db.prepare('SELECT 1 FROM saved_albums WHERE user_id = ? AND album_id = ?').get(this.user.id, String(id));
  }

  /** Сохранённые альбомы, недавно добавленные первыми. */
  savedAlbums(): SavedAlbum[] {
    const u = this.requireUser();
    const rows = this.db.prepare('SELECT * FROM saved_albums WHERE user_id = ? ORDER BY added_at DESC, rowid DESC').all(u.id) as SavedAlbumRow[];
    return rows.map(savedAlbumFromRow);
  }

  /** Снимок сохранённого альбома (страница альбома без сети) или null. */
  savedAlbum(id: string): SavedAlbum | null {
    if (!this.user) return null;
    const row = this.db.prepare('SELECT * FROM saved_albums WHERE user_id = ? AND album_id = ?').get(this.user.id, String(id)) as
      | SavedAlbumRow
      | undefined;
    return row ? savedAlbumFromRow(row) : null;
  }

  // ---------- где ещё нужна песня (скачанный файл не удаляем молча) ----------

  /** Где у этого пользователя есть песня: любимые, плейлисты, сохранённые альбомы. */
  whereUsed(c: Candidate): string[] {
    const u = this.requireUser();
    const out: string[] = [];
    const fav = this.db
      .prepare('SELECT 1 FROM favorites f JOIN tracks t ON t.id = f.track_id WHERE f.user_id = ? AND t.source = ? AND t.source_id = ?')
      .get(u.id, c?.source, c?.id);
    if (fav) out.push('Любимые треки');
    const pls = this.db
      .prepare(
        `SELECT DISTINCT p.name FROM playlist_items i JOIN playlists p ON p.id = i.playlist_id JOIN tracks t ON t.id = i.track_id
         WHERE p.user_id = ? AND t.source = ? AND t.source_id = ?`,
      )
      .all(u.id, c?.source, c?.id) as { name: string }[];
    for (const p of pls) out.push(`плейлист «${p.name}»`);
    for (const a of this.savedAlbums()) if (a.tracks.some((t) => t.source === c?.source && t.id === c?.id)) out.push(`альбом «${a.title}»`);
    return out;
  }

  /** id трека в базе (для учёта скачанного): создаёт запись, если её нет. */
  trackId(c: Candidate): number {
    return this.upsertTrack(c);
  }

  // ---------- избранные артисты ----------

  /** Ключ артиста: id страницы YouTube Music, если он известен, иначе имя. */
  static artistKey(a: { name: string; ytId?: string }): string {
    return a.ytId ? `yt:${a.ytId}` : `name:${String(a.name ?? '').trim().toLowerCase()}`;
  }

  favArtists(): FavArtist[] {
    const u = this.requireUser();
    // С новинкой первыми, как в макете
    const rows = this.db
      .prepare('SELECT * FROM fav_artists WHERE user_id = ? ORDER BY fresh IS NULL, added_at DESC')
      .all(u.id) as FavArtistRow[];
    return rows.map(favArtistFromRow);
  }

  isFavArtist(a: { name: string; ytId?: string }): boolean {
    if (!this.user) return false;
    return !!this.db
      .prepare('SELECT 1 FROM fav_artists WHERE user_id = ? AND artist_key = ?')
      .get(this.user.id, ProfileStore.artistKey(a));
  }

  /**
   * Добавить в избранные артисты или убрать. Возвращает новое состояние.
   * releases: релизы с открытой карточки, они считаются уже увиденными (кольца сразу не будет).
   */
  toggleFavArtist(a: { name: string; ytId?: string; thumbnail?: string; releases?: AlbumRef[] }): boolean {
    const u = this.requireUser();
    const name = String(a?.name ?? '').trim().slice(0, 200);
    if (!name) throw new ProfileError('bad_input', 'Нет имени артиста');
    const ytId = typeof a.ytId === 'string' && /^UC[\w-]{10,40}$/.test(a.ytId) ? a.ytId : undefined;
    const key = ProfileStore.artistKey({ name, ytId });
    const del = this.db.prepare('DELETE FROM fav_artists WHERE user_id = ? AND artist_key = ?').run(u.id, key);
    if (Number(del.changes) > 0) return false;
    const releases = cleanReleases(a.releases);
    const now = Date.now();
    this.db
      .prepare(
        `INSERT INTO fav_artists (user_id, artist_key, name, yt_id, thumbnail, added_at, seen_releases, releases, fresh, checked_at, opened_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?)`,
      )
      .run(u.id, key, name, ytId ?? null, cleanUrl(a.thumbnail), now, JSON.stringify(releases.map((r) => r.id)), JSON.stringify(releases), now, now);
    return true;
  }

  /** Карточка артиста открыта: все его текущие релизы считаются увиденными, кольцо "новый трек" пропадает. */
  markArtistOpened(a: { name: string; ytId?: string; thumbnail?: string }, releases: AlbumRef[]): void {
    if (!this.user) return;
    const key = ProfileStore.artistKey(a);
    const row = this.db.prepare('SELECT seen_releases FROM fav_artists WHERE user_id = ? AND artist_key = ?').get(this.user.id, key) as
      | { seen_releases: string }
      | undefined;
    if (!row) return;
    const list = cleanReleases(releases);
    const seen = new Set<string>([...parseJson<string[]>(row.seen_releases, []), ...list.map((r) => r.id)]);
    this.db
      .prepare(
        `UPDATE fav_artists SET seen_releases = ?, releases = CASE WHEN ? = '[]' THEN releases ELSE ? END, fresh = NULL,
           opened_at = ?, thumbnail = COALESCE(?, thumbnail) WHERE user_id = ? AND artist_key = ?`,
      )
      .run(JSON.stringify([...seen].slice(-500)), JSON.stringify(list), JSON.stringify(list), Date.now(), cleanUrl(a.thumbnail), this.user.id, key);
    // Карточку артиста открыли: его новинки больше не отмечены зелёной точкой
    this.db.prepare('UPDATE artist_releases SET opened = 1 WHERE user_id = ? AND artist_key = ?').run(this.user.id, key);
  }

  /** Избранные артисты, которых давно не проверяли на новинки. */
  favArtistsDue(olderThanMs: number): FavArtist[] {
    if (!this.user) return [];
    const rows = this.db
      .prepare('SELECT * FROM fav_artists WHERE user_id = ? AND checked_at < ? ORDER BY checked_at')
      .all(this.user.id, Date.now() - olderThanMs) as FavArtistRow[];
    return rows.map(favArtistFromRow);
  }

  /**
   * Результат проверки новинок: свежие релизы артиста. Если среди них есть то, чего человек
   * ещё не видел, это становится "новинкой" (кольцо на главной), пока он не откроет карточку.
   */
  updateArtistReleases(key: string, releases: AlbumRef[], thumbnail?: string): void {
    if (!this.user) return;
    const row = this.db.prepare('SELECT seen_releases, fresh, name, yt_id FROM fav_artists WHERE user_id = ? AND artist_key = ?').get(this.user.id, key) as
      | { seen_releases: string; fresh: string | null; name: string; yt_id: string | null }
      | undefined;
    if (!row) return;
    const list = cleanReleases(releases);
    const seen = new Set(parseJson<string[]>(row.seen_releases, []));
    const unseen = list.find((r) => !seen.has(r.id));
    const keepOld = row.fresh && !seen.has(parseJson<AlbumRef | null>(row.fresh, null)?.id ?? '') ? row.fresh : null;
    this.db
      .prepare('UPDATE fav_artists SET releases = ?, fresh = ?, checked_at = ?, thumbnail = COALESCE(?, thumbnail) WHERE user_id = ? AND artist_key = ?')
      .run(JSON.stringify(list), unseen ? JSON.stringify(unseen) : keepOld, Date.now(), cleanUrl(thumbnail), this.user.id, key);
    // «Новинки»: каждый ещё не виденный релиз запоминаем с моментом, когда его заметили
    const add = this.db.prepare(
      `INSERT OR IGNORE INTO artist_releases (user_id, release_id, artist_key, artist, artist_yt, title, kind, year, thumbnail, found_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    );
    const now = Date.now();
    for (const r of list.filter((x) => !seen.has(x.id))) add.run(this.user.id, r.id, key, row.name, row.yt_id, r.title, r.kind, r.year ?? null, r.thumbnail ?? null, now);
  }

  /**
   * Новинки избранных артистов: релизы, которые проверка заметила за последние days дней (null: все), новые сверху.
   * opened: человек уже открывал релиз или карточку артиста (зелёной точки нет).
   */
  newReleases(days: number | null = 28): NewRelease[] {
    if (!this.user) return [];
    const since = days === null ? 0 : Date.now() - days * 24 * 60 * 60_000;
    const rows = this.db
      .prepare(
        `SELECT r.* FROM artist_releases r JOIN fav_artists f ON f.user_id = r.user_id AND f.artist_key = r.artist_key
         WHERE r.user_id = ? AND r.found_at >= ? ORDER BY r.found_at DESC, r.year DESC LIMIT 200`,
      )
      .all(this.user.id, since) as ReleaseRow[];
    return rows.map((r) => ({
      id: r.release_id,
      title: r.title,
      kind: r.kind === 'single' ? 'single' : 'album',
      year: r.year ?? undefined,
      thumbnail: r.thumbnail ?? undefined,
      artist: r.artist,
      artistYt: r.artist_yt ?? undefined,
      foundAt: r.found_at,
      opened: !!r.opened,
    }));
  }

  /** Релиз открыт: зелёная точка у новинки пропадает. */
  markReleaseOpened(id: string): void {
    if (!this.user) return;
    this.db.prepare('UPDATE artist_releases SET opened = 1 WHERE user_id = ? AND release_id = ?').run(this.user.id, String(id));
  }

  // ---------- «Не нравится»: скрытое из волны ----------

  /** Скрыть песню или артиста из волны и «Включить похожее». */
  hide(kind: 'track' | 'artist', c: Candidate, artistName?: string): void {
    const u = this.requireUser();
    const t = checkCandidate(c);
    const name = String(artistName ?? t.artist).trim().slice(0, 200);
    const key = kind === 'track' ? `${t.source}:${t.id}` : name.toLowerCase();
    this.db
      .prepare(
        `INSERT INTO hidden (user_id, kind, key, title, artist, thumbnail, data, added_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT (user_id, kind, key) DO UPDATE SET added_at = excluded.added_at`,
      )
      .run(u.id, kind, key, kind === 'track' ? t.title : name, kind === 'track' ? t.artist : null, t.thumbnail ?? null, JSON.stringify(t), Date.now());
  }

  unhide(kind: 'track' | 'artist', key: string): void {
    const u = this.requireUser();
    this.db.prepare('DELETE FROM hidden WHERE user_id = ? AND kind = ? AND key = ?').run(u.id, kind, String(key));
  }

  hiddenList(): HiddenItem[] {
    const u = this.requireUser();
    const rows = this.db.prepare('SELECT * FROM hidden WHERE user_id = ? ORDER BY added_at DESC').all(u.id) as HiddenRow[];
    return rows.map((r) => ({ kind: r.kind, key: r.key, title: r.title, artist: r.artist ?? undefined, thumbnail: r.thumbnail ?? undefined, addedAt: r.added_at }));
  }

  /** Для подбора волны: ключи скрытых песен и имена скрытых артистов (в нижнем регистре). Без входа: пусто. */
  hiddenKeys(): { tracks: Set<string>; artists: Set<string> } {
    const out = { tracks: new Set<string>(), artists: new Set<string>() };
    if (!this.user) return out;
    for (const r of this.db.prepare('SELECT kind, key FROM hidden WHERE user_id = ?').all(this.user.id) as { kind: string; key: string }[]) {
      (r.kind === 'artist' ? out.artists : out.tracks).add(r.key);
    }
    return out;
  }

  // ---------- недавние запросы поиска, артисты и альбомы ----------

  addRecent(kind: RecentKind, key: string, label: string, data?: unknown): void {
    if (!this.user || !['query', 'artist', 'album'].includes(kind)) return;
    const k = String(key ?? '').trim().slice(0, 200);
    const l = String(label ?? '').trim().slice(0, 200);
    if (!k || !l) return;
    const u = this.user;
    this.db.transaction(() => {
      this.db
        .prepare(
          `INSERT INTO recents (user_id, kind, key, label, data, at) VALUES (?, ?, ?, ?, ?, ?)
           ON CONFLICT (user_id, kind, key) DO UPDATE SET label = excluded.label, data = excluded.data, at = excluded.at`,
        )
        .run(u.id, kind, k, l, data === undefined ? null : JSON.stringify(data).slice(0, 2000), Date.now());
      this.db
        .prepare(
          `DELETE FROM recents WHERE user_id = ? AND kind = ? AND key NOT IN
           (SELECT key FROM recents WHERE user_id = ? AND kind = ? ORDER BY at DESC LIMIT 10)`,
        )
        .run(u.id, kind, u.id, kind);
    })();
  }

  recents(): RecentItem[] {
    if (!this.user) return [];
    const rows = this.db.prepare('SELECT kind, key, label, data, at FROM recents WHERE user_id = ? ORDER BY at DESC, rowid DESC').all(this.user.id) as RecentRow[];
    return rows.map((r) => ({ kind: r.kind, key: r.key, label: r.label, data: parseJson<Record<string, string> | null>(r.data, null) ?? undefined, at: r.at }));
  }

  removeRecent(kind: RecentKind, key: string): void {
    const u = this.requireUser();
    this.db.prepare('DELETE FROM recents WHERE user_id = ? AND kind = ? AND key = ?').run(u.id, kind, String(key));
  }

  clearRecents(): void {
    const u = this.requireUser();
    this.db.prepare('DELETE FROM recents WHERE user_id = ?').run(u.id);
  }

  // ---------- звук (1.7): одинаковая громкость и эквалайзер, у каждого профиля свои ----------

  audioSettings(): AudioSettings {
    const u = this.requireUser();
    try {
      return cleanAudio(JSON.parse(this.getSetting(`audio.${u.id}`) ?? 'null'));
    } catch {
      return cleanAudio(null);
    }
  }

  setAudioSettings(next: Partial<AudioSettings>): AudioSettings {
    const u = this.requireUser();
    const cur = this.audioSettings();
    const v = cleanAudio({ ...cur, ...next, eq: { ...cur.eq, ...(next.eq ?? {}) } });
    this.setSetting(`audio.${u.id}`, JSON.stringify(v));
    return v;
  }

  // ---------- настройки ----------

  private getSetting(key: string): string | null {
    const row = this.db.prepare('SELECT value FROM settings WHERE key = ?').get(key) as { value: string } | undefined;
    return row?.value ?? null;
  }

  private setSetting(key: string, value: string): void {
    this.db
      .prepare('INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value')
      .run(key, value);
  }
}
